(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7540],{3559:function(e,t,n){(window.__NEXT_P=window.__NEXT_P||[]).push(["/people/mostafa_ammar",function(){return n(6580)}])},6580:function(e,t,n){"use strict";n.r(t),n.d(t,{useTOC:function(){return i}});var o=n(2676),a=n(2837),r=n(2339),s=n(146);function i(e){return[]}t.default=(0,a.c)(function(e){let t={p:"p",...(0,s.a)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"Mostafa Ammar is a Regents’ Professor with the School of Computer Science at the Georgia Institute of Technology. He served as Associate Chair of the School of Computer Science from 2006 to 2012. Dr. Ammar received the S.B. and S.M. degrees from the Massachusetts Institute of Technology and the Ph.D. degree from the University of Waterloo, Ontario, Canada."}),"\n",(0,o.jsx)(t.p,{children:"Dr. Ammar’s research interests are in network architectures, protocols and services. He has contributions in the areas of multicast communication and services, multimedia streaming, content distribution networks, network simulation, disruption-tolerant networks, and most recently, in mobile cloud computing and network virtualization. He has published extensively in these areas. Over the years he has received funding for his research from federal and defense agencies and national and local industries including NSF, DARPA, AFOSR, ARL, CISCO, IBM, Intel, BellSouth and Sprint. To date, 35 PhD students have completed their degrees under his supervision; many have gone on to distinguished careers in academia and industry. He is the co-author of the textbook “Fundamentals of Telecommunication Networks” published by Wiley-Interscience in 1994."}),"\n",(0,o.jsx)(t.p,{children:"Dr. Ammar has served the networking research community in multiple roles. Most notably, he served as the Editor-in-Chief of the IEEE/ACM Transactions on Networking (ToN) from 1999 to 2003, and he was the co-TPC Chair for the IEEE ICNP 1997, ACM CoNEXT 2006 and ACM SIGMETRICS 2007 conferences. He currently serves on the steering committee of the IEEE Transactions on Mobile Computing. His awards include the IBM Faculty Partnership Award (1996), Best Paper Award at the 7th WWW conference (1998), the GT Outstanding Doctoral Thesis Advisor Award (2006) and the Outstanding Service Award from the IEEE Technical Committee on Computer Communications (2010), the ACM Mobihoc Best Paper Award (2012), College of Computing Faculty Mentor Award (2015) and the GT Course Survey Teaching Effectiveness Award (2013, 2014, 2015, and 2016)."}),"\n",(0,o.jsx)(t.p,{children:"Dr. Ammar was elected Fellow of the IEEE in 2002 and Fellow of the ACM in 2003."})]})},"/people/mostafa_ammar",{filePath:"pages/people/mostafa_ammar.mdx",pageMap:r.v,frontMatter:{title:"Mostafa Ammar",image:"/people/m7.png",role:"Professor\nGeorgia Institute of Technology",category:"C2_1",date:"2026/08/27",google_scholar:"https://scholar.google.com/citations?user=OT79Y9UAAAAJ&hl=en",website:"https://www.cc.gatech.edu/people/mostafa-ammar"},title:"Mostafa Ammar"},"undefined"==typeof RemoteContent?i:RemoteContent.useTOC)}},function(e){e.O(0,[2837,2339,2888,9774,179],function(){return e(e.s=3559)}),_N_E=e.O()}]);